import { createHash } from 'node:crypto';
import { OG_IMAGE_BASE64 } from './og-image-data.js';

/**
 * The link preview image of the public pages (Open Graph, X cards, chat apps). Generated by
 * `scripts/og-image.mjs`; the address carries a content hash so previews refresh after a change.
 */
export const OG_IMAGE_PNG = Buffer.from(OG_IMAGE_BASE64, 'base64');

export const OG_IMAGE_PATH = `/assets/og.png?v=${createHash('sha256').update(OG_IMAGE_PNG).digest('hex').slice(0, 12)}`;
